//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error represents a failure that may be retried.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry after `retry_index` previous retries.
    pub(crate) fn delay_for_retry(&self, retry_index: u32) -> u64 {
        self.base_delay_ms
            .min(self.max_delay_ms)
            .saturating_mul(2u64.saturating_pow(retry_index))
            .min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_saturates_without_overflow() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: u64::MAX,
            max_delay_ms: 99,
        };

        assert_eq!(config.delay_for_retry(u32::MAX), 99);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let mut retry_index = 0;

    for attempt in 0..config.max_attempts {
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() => return Err(error),
            Err(error) => {
                if attempt + 1 == config.max_attempts {
                    return Err(error);
                }
                sleeper.sleep_ms(config.delay_for_retry(retry_index));
                retry_index += 1;
            }
        }
    }

    // `RetryConfig::max_attempts` is documented as being at least one. This
    // fallback keeps the function total if an invalid zero value is supplied.
    job()
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

fn config(max_attempts: u32) -> RetryConfig {
    RetryConfig {
        max_attempts,
        base_delay_ms: 10,
        max_delay_ms: 25,
    }
}

#[test]
fn retries_transient_errors_with_bounded_exponential_delays() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(5), &mut sleeper, || {
        calls += 1;
        if calls < 5 {
            Err(RetryError::Transient("temporary outage".into()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 5);
    assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
}

#[test]
fn permanent_errors_return_without_retrying() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(5), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("invalid job".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid job".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn max_attempts_includes_first_call() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(3), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("still unavailable".into()))
    });

    assert_eq!(result, Err(RetryError::Transient("still unavailable".into())));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![10, 20]);
}

#[test]
fn very_large_retry_counts_do_not_overflow_delay_calculation() {
    let retry_config = RetryConfig {
        max_attempts: u32::MAX,
        base_delay_ms: u64::MAX,
        max_delay_ms: 7,
    };

    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&retry_config, &mut sleeper, || {
        calls += 1;
        if calls == 2 {
            Ok(())
        } else {
            Err(RetryError::Transient("temporary".into()))
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 2);
    assert_eq!(sleeper.sleeps, vec![7]);
}
